fn relax(dist: List[Int], edge: List[Int]) -> List[Int] {
  let u = edge.get_or(0, 0)
  let v = edge.get_or(1, 0)
  let w = edge.get_or(2, 0)
  let d_u = dist.get_or(u, -1)
  if d_u < 0 {
    return dist
  }
  let d_v = dist.get_or(v, -1)
  let cand = d_u + w
  if d_v < 0 or cand < d_v {
    return dist.set(v, cand)
  }
  return dist
}

fn sweep(dist: List[Int], edges: List[List[Int]]) -> List[Int] {
  return edges.fold(dist, fn(d, e) => relax(d, e))
}

fn settle(dist: List[Int], edges: List[List[Int]], rounds: Int) -> List[Int] {
  if rounds <= 0 {
    return dist
  }
  return settle(dist: sweep(dist: dist, edges: edges), edges: edges, rounds: rounds - 1)
}

pub fn paths(n: Int, edges: List[List[Int]], src: Int) -> List[Int] {
  let start = range(0, n).map(fn(_i) => -1).set(src, 0)
  return settle(dist: start, edges: edges, rounds: n)
}
